import{_ as s}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o as t,c as a,a as i}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const f=JSON.parse(`{"title":"What's new in v1.7.0","description":"Shell completions for bash, zsh and fish, plus extended syntax highlighting for PHP, C/C++, Swift, Terraform/HCL and Dockerfile.","frontmatter":{"title":"What's new in v1.7.0","description":"Shell completions for bash, zsh and fish, plus extended syntax highlighting for PHP, C/C++, Swift, Terraform/HCL and Dockerfile.","date":"2026-03-04T00:00:00.000Z"},"headers":[],"relativePath":"blog/release-v1-7-0.md","filePath":"blog/release-v1-7-0.md"}`),o={name:"blog/release-v1-7-0.md"};function d(c,e,h,l,n,r){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="what-s-new-in-github-code-search-v1-7-0" tabindex="-1">What&#39;s new in github-code-search v1.7.0 <a class="header-anchor" href="#what-s-new-in-github-code-search-v1-7-0" aria-label="Permalink to &quot;What&#39;s new in github-code-search v1.7.0&quot;">​</a></h1><blockquote><p>Full release notes: <a href="https://github.com/fulll/github-code-search/releases/tag/v1.7.0" target="_blank" rel="noreferrer">https://github.com/fulll/github-code-search/releases/tag/v1.7.0</a></p></blockquote><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><h3 id="shell-completions-—-bash-zsh-fish" tabindex="-1">Shell completions — bash, zsh, fish <a class="header-anchor" href="#shell-completions-—-bash-zsh-fish" aria-label="Permalink to &quot;Shell completions — bash, zsh, fish&quot;">​</a></h3><p>Tab-completion is now available for all three major shells. A new <code>completions</code> subcommand prints the appropriate script to stdout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;"># bash</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> completions</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --shell</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#A0111F;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> ~/.bashrc</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;"># zsh  (place the script in a $fpath directory)</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> completions</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --shell</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> zsh</span><span style="--shiki-light:#A0111F;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> ~/.zfunc/_github-code-search</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;"># fish</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> completions</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --shell</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fish</span><span style="--shiki-light:#A0111F;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> ~/.config/fish/completions/github-code-search.fish</span></span></code></pre></div><p>When <code>--shell</code> is omitted, the shell is auto-detected from <code>$SHELL</code>.</p><p>The completion scripts cover:</p><ul><li>All subcommands (<code>query</code>, <code>upgrade</code>, <code>completions</code>)</li><li>All flags (<code>--org</code>, <code>--format</code>, <code>--output-type</code>, <code>--exclude-repositories</code>, <code>--exclude-extracts</code>, <code>--group-by-team-prefix</code>, <code>--no-interactive</code>, <code>--include-archived</code>, <code>--no-cache</code>, <code>--debug</code>)</li><li>Enumerated flag values where applicable (<code>--format markdown|json</code>, <code>--output-type repo-and-matches|repo-only</code>)</li></ul><h4 id="auto-refresh-on-upgrade" tabindex="-1">Auto-refresh on upgrade <a class="header-anchor" href="#auto-refresh-on-upgrade" aria-label="Permalink to &quot;Auto-refresh on upgrade&quot;">​</a></h4><p>If you have installed completions, they are <strong>refreshed automatically</strong> every time you run <code>github-code-search upgrade</code>. No manual action needed — the completion file is overwritten in-place.</p><h4 id="install-script" tabindex="-1">Install script <a class="header-anchor" href="#install-script" aria-label="Permalink to &quot;Install script&quot;">​</a></h4><p>The <code>install.sh</code> script now calls <code>install_completions()</code> at the end of an installation, writing the completion file for the detected shell:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> -sSL</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/fulll/github-code-search/main/install.sh</span><span style="--shiki-light:#A0111F;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><h3 id="extended-syntax-highlighting" tabindex="-1">Extended syntax highlighting <a class="header-anchor" href="#extended-syntax-highlighting" aria-label="Permalink to &quot;Extended syntax highlighting&quot;">​</a></h3><p>Five new language profiles have been added to the TUI code viewer:</p><table tabindex="0"><thead><tr><th>Language</th><th>Keywords → magenta</th><th>Special tokens → cyan</th></tr></thead><tbody><tr><td><strong>PHP</strong></td><td><code>function</code>, <code>class</code>, <code>echo</code>, <code>foreach</code>…</td><td><code>$variables</code>, PascalCase types — <code>#[Attributes]</code> correctly NOT dimmed (PHP 8+)</td></tr><tr><td><strong>C / C++</strong></td><td><code>int</code>, <code>void</code>, <code>struct</code>, <code>class</code>, <code>nullptr</code>…</td><td><code>#include</code>/<code>#define</code> directives</td></tr><tr><td><strong>Swift</strong></td><td><code>var</code>, <code>let</code>, <code>func</code>, <code>guard</code>, <code>protocol</code>…</td><td>PascalCase types</td></tr><tr><td><strong>Terraform/HCL</strong></td><td><code>resource</code>, <code>variable</code>, <code>output</code>, <code>module</code>…</td><td>Booleans / <code>null</code></td></tr><tr><td><strong>Dockerfile</strong></td><td><code>FROM</code>, <code>RUN</code>, <code>CMD</code>, <code>COPY</code>, <code>EXPOSE</code>…</td><td><code>$ENV_VAR</code> / <code>\${VAR}</code> references</td></tr></tbody></table><p>Language detection is extension-based first (<code>Dockerfile.ts</code> is correctly identified as TypeScript, not Dockerfile). Filename-based Dockerfile detection is the fallback for files without a known extension.</p><p>12 new file extensions are now recognised: <code>.php</code>, <code>.phtml</code>, <code>.c</code>, <code>.h</code>, <code>.cpp</code>, <code>.cc</code>, <code>.cxx</code>, <code>.hpp</code>, <code>.hxx</code>, <code>.swift</code>, <code>.tf</code>, <code>.hcl</code>.</p><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><p>Or grab the latest binary directly from the <a href="https://github.com/fulll/github-code-search/releases/tag/v1.7.0" target="_blank" rel="noreferrer">GitHub Releases page</a>.</p>`,23)])])}const m=s(o,[["render",d]]);export{f as __pageData,m as default};
